import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ categories = [], onSave }) {
  const [limits, setLimits] = useState({});

  const handleChange = (category, value) => {
    setLimits((prev) => ({
      ...prev,
      [category]: value
    }));
  };

  const handleSave = () => {
    if (onSave) onSave(limits);
  };

  return (
    <div className="income-container">
      <h2 className="income-title">Set Monthly Budget Limits</h2>

      {/* ⭐ If no categories selected */}
      {categories.length === 0 && (
        <p className="income-subtitle">
          No categories selected with priority ≥ 3
        </p>
      )}

      <div className="income-grid">
        {categories.map((category) => (
          <div key={category} className="income-card">
            <div className="income-name">{category}</div>

            {/* ⭐ Input box ALWAYS visible */}
            <input
              type="number"
              placeholder="Enter amount"
              value={limits[category] || ""}
              onChange={(e) => handleChange(category, e.target.value)}
              style={{
                marginTop: "15px",
                width: "100%",
                padding: "12px",
                borderRadius: "10px",
                border: "1px solid #dcdcdc",
                fontSize: "15px"
              }}
            />
          </div>
        ))}
      </div>

      {categories.length > 0 && (
        <button className="next-button" onClick={handleSave}>
          Save Budget
        </button>
      )}
    </div>
  );
}

export default BudgetLimits;
